<?php namespace Workspace; $today=gmdate('Y-m-d');$entitiesMap=array_column($entities,'name','id');$bound=[];$free=[];foreach($projects as $p){if((int)$p['entity_id']===$entityId)$bound[$p['id']]=$p['title'];if($p['entity_id']===null)$free[$p['id']]=$p['title'];}$supplierMap=array_column($suppliers,'name','id');$hidden=static function()use($entityId){echo '<input type="hidden" name="entity_id" value="',h($entityId),'">';}; ?>
<section class="panel"><h2>Финансовые книги по юрлицам</h2><p>Управленческий журнал. Одна касса, независимые периоды юрлиц. Суммы не конвертируются. <a href="<?= h(url('accounting')) ?>">Общий журнал</a> · <a href="<?= h(url('payments')) ?>">Согласование платежей</a></p>
<?php if(!$active): ?><p>Сначала примите начальные остатки в общем журнале.</p><?php endif ?>
<?php if(!$entities): ?><p>Создайте юрлицо в разделе счетов.</p><?php else: ?><form method="get"><input type="hidden" name="p" value="books"><label>Юрлицо<select name="entity"><?php selectOptions($entitiesMap,$entityId) ?></select></label><button>Открыть книгу</button></form><?php endif ?></section>
<?php if($entityId): ?>
<section class="panel"><h2>Распределение</h2><p>Проекты книги: <?= h(implode(', ',$bound)?:'нет') ?>. Привязка неизменяема; учитывает прежние проводки проекта.</p><?php if($owner&&$active&&$free): ?><form method="post"><?php formFields('books.assign');$hidden() ?><label>Проект<select name="project_id"><?php selectOptions($free) ?></select></label><button>Закрепить за юрлицом</button></form><?php endif ?>
<?php if($owner&&$active&&$openings): ?><form method="post"><?php formFields('books.allocate');$hidden() ?><label>Нераспределённая начальная проводка<select name="entry_id"><?php foreach($openings as $j): ?><option value="<?= h($j['id']) ?>">#<?= h($j['id'].' · '.$j['currency'].' '.money((int)$j['amount_minor']).' · '.$j['memo']) ?></option><?php endforeach ?></select></label><button>Распределить целиком</button></form><?php endif ?></section>
<section class="panel"><h2>Периоды</h2><form method="get"><input type="hidden" name="p" value="books"><input type="hidden" name="entity" value="<?= h($entityId) ?>"><label>Период<select name="period"><?php foreach($periods as $p): ?><option value="<?= h($p['id']) ?>" <?= (int)($period['id']??0)===(int)$p['id']?'selected':'' ?>><?= h($p['starts_on'].' — '.$p['ends_on'].($p['closed_at']?' · закрыт':' · открыт')) ?></option><?php endforeach ?></select></label><button>Показать</button></form>
<?php if($owner&&$active): ?><form method="post"><?php formFields('books.period');$hidden() ?><label>Начало<input type="date" name="starts_on" required value="<?= h(gmdate('Y-m-01')) ?>"></label><label>Конец<input type="date" name="ends_on" required value="<?= h(gmdate('Y-m-t')) ?>"></label><button>Создать период</button></form><?php if($period&&$period['closed_at']===null&&$period['ends_on']<$today): ?><form method="post"><?php formFields('books.close');$hidden() ?><input type="hidden" name="id" value="<?= h($period['id']) ?>"><p>Закрытие необратимо; новые проводки с датой до конца периода блокируются.</p><button>Закрыть книгу за период</button></form><?php endif;endif ?></section>
<?php endif ?>
<?php foreach(['Оборотно-сальдовая ведомость юрлица'=>$trial,'Нераспределённый остаток организации (не входит в книгу)'=>$unallocated] as $title=>$rows): ?><section class="panel"><h2><?= h($title) ?></h2><?php if(!$rows): ?><p>Нет проводок.</p><?php endif ?><div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Счёт</th><th>Начало</th><th>Дебет</th><th>Кредит</th><th>Конец</th></tr></thead><tbody><?php foreach($rows as $c=>$accounts)foreach($accounts as $code=>$r): ?><tr><td><?= h($c) ?></td><td><?= h($code) ?></td><?php foreach(['opening','debit','credit','closing'] as $k): ?><td><?= h(money($r[$k])) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div></section><?php endforeach ?>
<?php if($entityId): ?><section class="panel"><h2>Счета поставщиков и задолженность на сегодня</h2><p>Начисление: Дт AP-EXP, Кт AP-LIAB. Оплата после независимого подтверждения: Дт AP-LIAB, Кт 1000. Суммы включая применимые налоги; налоговые вычеты не рассчитываются.</p><div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Долг</th><th>Просрочено</th><th>Ожидает согласования</th><th>Возвраты на согласовании</th></tr></thead><tbody><?php foreach($totals as $c=>$t): ?><tr><td><?= h($c) ?></td><?php foreach(['outstanding','overdue','pending','pending_refund'] as $k): ?><td><?= h(money($t[$k])) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div>
<?php if($writable&&$active&&$bound&&$supplierMap): ?><details><summary>Зарегистрировать счёт поставщика / начисление</summary><form method="post"><?php formFields('books.bill');$hidden() ?><label>Проект<select name="project_id"><?php selectOptions($bound) ?></select></label><label>Поставщик<select name="supplier_id"><?php selectOptions($supplierMap) ?></select></label><label>Номер документа<input name="reference" required maxlength="180"></label><label>Дата начисления<input type="date" name="booked_on" value="<?= h($today) ?>" required></label><label>Срок оплаты<input type="date" name="due_on" required></label><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES)) ?></select></label><label>Сумма<input name="amount" required></label><label>Основание<input name="memo" maxlength="400" required></label><button>Начислить</button></form></details><?php endif ?>
<?php foreach($bills as $b): ?><article class="panel"><h3>#<?= h($b['id'].' · '.$b['supplier_name'].' · '.$b['reference']) ?></h3><p><?= h($b['currency'].' '.money((int)$b['amount_minor']).' · дата '.$b['booked_on'].' · срок '.$b['due_on']) ?><?= $b['cancelled_entry_id']?' · отменён':'' ?></p><p>Оплачено <?= h(money($b['paid'])) ?> · долг <?= h(money($b['outstanding'])) ?> · ожидает <?= h(money($b['pending'])) ?> · проводка #<?= h($b['entry_id']) ?></p>
<?php if($b['movements']): ?><ul><?php foreach($b['movements'] as $m): ?><li><?= h('#'.$m['id'].' · '.$m['kind'].' · '.$m['reference'].' · '.$m['status'].' · '.money((int)$m['amount_minor'])) ?></li><?php endforeach ?></ul><?php endif ?>
<?php if($writable&&$active&&!$b['cancelled_entry_id']): ?><?php if($b['available']>0): ?><details><summary>Заявка на оплату</summary><form method="post"><?php formFields('books.pay');$hidden() ?><input type="hidden" name="id" value="<?= h($b['id']) ?>"><label>Сумма<input name="amount" value="<?= h(money($b['available'],false)) ?>" required></label><label>Дата фактической оплаты<input type="date" name="booked_on" value="<?= h($today) ?>" required></label><label>Идентификатор платежа<input name="reference" required maxlength="180"></label><button>На согласование</button></form></details><?php endif ?><?php if($b['paid']>$b['pending_refund']): ?><details><summary>Возврат от поставщика</summary><form method="post"><?php formFields('books.refund');$hidden() ?><input type="hidden" name="id" value="<?= h($b['id']) ?>"><label>Исходная оплата<select name="original_request_id"><?php foreach($b['movements'] as $m)if($m['kind']==='payment'&&$m['status']==='posted'): ?><option value="<?= h($m['id']) ?>"><?= h('#'.$m['id'].' · '.money((int)$m['amount_minor'])) ?></option><?php endif ?></select></label><label>Сумма возврата<input name="amount" required></label><label>Дата возврата<input type="date" name="booked_on" value="<?= h($today) ?>" required></label><label>Идентификатор возврата<input name="reference" required maxlength="180"></label><button>На согласование</button></form></details><?php endif ?><?php if(!$b['paid']&&!$b['pending']&&!$b['pending_refund']): ?><details><summary>Сторно неоплаченного начисления</summary><form method="post"><?php formFields('books.cancel');$hidden() ?><input type="hidden" name="id" value="<?= h($b['id']) ?>"><label>Дата<input type="date" name="booked_on" value="<?= h($today) ?>" required></label><label>Основание<input name="memo" maxlength="400" required></label><button>Сторнировать</button></form></details><?php endif;endif ?></article><?php endforeach ?>
<?php if($nextBefore): ?><a href="<?= h(url('books',['entity'=>$entityId,'before'=>$nextBefore])) ?>">Следующие счета</a><?php endif ?></section><?php endif ?>

<section class="panel"><h2>Контроль остатков по валютам на конец выбранного периода</h2><div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Касса всех книг</th><th>Нераспределено</th><th>Общий журнал</th><th>Сверка</th></tr></thead><tbody><?php foreach($cashControl as $c=>$r): ?><tr><td><?= h($c) ?></td><?php foreach(['assigned','unallocated','ledger'] as $k): ?><td><?= h(money($r[$k])) ?></td><?php endforeach ?><td><?= $r['ok']?'Совпадает':'Расхождение' ?></td></tr><?php endforeach ?></tbody></table></div>
<?php if($entityId): ?><h3>Сверка обязательств выбранного юрлица</h3><div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Кредитовый остаток AP-LIAB</th><th>Долг поставщикам</th><th>Сверка</th></tr></thead><tbody><?php foreach($payableControl as $c=>$r): ?><tr><td><?= h($c) ?></td><td><?= h(money($r['ledger'])) ?></td><td><?= h(money($r['debt'])) ?></td><td><?= $r['ok']?'Совпадает':'Расхождение' ?></td></tr><?php endforeach ?></tbody></table></div><h3>Задолженность по поставщикам на конец периода</h3><ul><?php foreach($payables['rows'] as $r): ?><li><?= h($r['supplier_name'].' · '.$r['currency'].' '.money($r['outstanding'])) ?></li><?php endforeach ?></ul><?php endif ?></section>
